/* één bestand: de audio zit in de pagina; maak er bij het laden blob-adressen van */
(function () {
  const A = window.__AUDIO || {};
  for (const ch of window.FILM.chapters) {
    const b64 = A[ch.audio]; if (!b64) continue;
    const bin = atob(b64), n = bin.length, u = new Uint8Array(n);
    for (let i = 0; i < n; i++) u[i] = bin.charCodeAt(i);
    ch.audio = URL.createObjectURL(new Blob([u], { type: 'audio/mpeg' }));
  }
  window.__AUDIO = null;
})();
